// Patches Next.js 15.4.10 css-minimizer-plugin to skip cssnano.
// cssnano-simple crashes on `hsl(var(--x) / alpha)` generated by Tailwind alpha modifiers.
// This makes optimizeAsset return the CSS unchanged instead of running cssnano.
"use strict";
const fs = require("fs");
const path = require("path");

try {
  const pluginPath = require.resolve(
    "next/dist/build/webpack/plugins/css-minimizer-plugin"
  );
  const content = fs.readFileSync(pluginPath, "utf8");

  if (content.includes("// PATCHED")) {
    console.log("css-minimizer-plugin.js already patched, skipping");
    process.exit(0);
  }

  const SEARCH = `    optimizeAsset(file, asset) {
        const postcssOptions = {`;

  const REPLACE = `    optimizeAsset(file, asset) {
        // PATCHED: return CSS as-is, skip cssnano (hsl(var()/alpha) crash workaround)
        const rawInput = asset.sourceAndMap ? asset.sourceAndMap().source : asset.source();
        return Promise.resolve(new _webpack.sources.RawSource(rawInput));
        const postcssOptions = {`;

  if (!content.includes(SEARCH)) {
    console.log(
      "css-minimizer-plugin.js: expected pattern not found, skipping patch"
    );
    process.exit(0);
  }

  fs.writeFileSync(pluginPath, content.replace(SEARCH, REPLACE));
  console.log("css-minimizer-plugin.js patched successfully");
} catch (e) {
  console.warn("css-minimizer-plugin patch failed (non-fatal):", e.message);
}
